/bin/bash -lc "cat > /tmp/forma-check/check.mjs <<'EOF'
import { chromium } from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1000}});
const errors=[];
page.on('pageerror',error=>errors.push(error.message));
await page.goto('http://localhost:5175/');
await page.evaluate(()=>document.fonts.ready);
await page.screenshot({path:'/tmp/forma-desktop.png',fullPage:true});
const trigger=page.getByRole('button',{name:'Показать уведомление'});
assert.equal(await page.locator('.live-notice').count(),0);
await page.locator('#duration').fill('2');
await trigger.click();
await page.locator('.live-notice').waitFor();
await page.waitForTimeout(1200);
await trigger.click();
await page.waitForTimeout(1100);
assert.equal(await page.locator('.live-notice').count(),1,'Repeat click restarts timer');
await page.locator('.live-notice').waitFor({state:'detached',timeout:2000});
await page.getByRole('button',{name:'Ошибка',exact:true}).click();
await page.locator('#message').fill('Проверка уведомления');
await page.locator('#position').selectOption('top-right');
await trigger.click();
assert.equal(await page.locator('.toast-region.top-right .error').count(),1);
assert.equal(await page.locator('.live-notice p').textContent(),'Проверка уведомления');
await page.getByRole('button',{name:'Закрыть уведомление'}).click();
assert.equal(await page.locator('.live-notice').count(),0);
await page.getByRole('button',{name:'Сбросить настройки'}).click();
assert.equal(await page.locator('#duration').inputValue(),'5');
assert.equal(await page.locator('#position').inputValue(),'bottom-right');
assert.equal(await page.locator('#message').inputValue(),'Изменения успешно сохранены.');
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/forma-mobile.png',fullPage:true});
assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth),true,'No horizontal overflow');
await trigger.click();
const rect=await page.locator('.live-notice').boundingBox();
assert(rect.x>=0 && rect.x+rect.width<=390 && rect.y>=0 && rect.y+rect.height<=844);
assert.deepEqual(errors,[]);
console.log('PASS: trigger, automatic dismissal, repeated click, message/type/position settings, manual close, reset, mobile layout, no browser errors.');
await browser.close();
EOF"

/bin/bash -lc "cat > src/toast.smoke.test.tsx <<'EOF'
import { test, expect, vi } from 'vitest';
import { JSDOM } from '/tmp/forma-check/node_modules/jsdom/lib/api.js';
import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';

test('toast appears, restarts its timer, dismisses automatically and closes manually', async () => {
  const dom = new JSDOM('<"'!doctype html><html><body><div id="test-root"></div></body></html>'"', { url: 'http://localhost' });
  vi.stubGlobal('window', dom.window);
  vi.stubGlobal('document', dom.window.document);
  vi.stubGlobal('navigator', dom.window.navigator);
  vi.stubGlobal('IS_REACT_ACT_ENVIRONMENT', true);
  vi.useFakeTimers();
  const root = createRoot(document.getElementById('test-root')"'!);
  await act(async () => root.render(<App />));
  const click = async (selector: string) => {
    await act(async () => document.querySelector(selector)!.dispatchEvent(new dom.window.MouseEvent('"'click', { bubbles: true })));
  };
  expect(document.querySelector('.live-notice')).toBeNull();
  await click('.trigger-button');
  expect(document.querySelector('.live-notice')?.textContent).toContain('Изменения успешно сохранены.');
  await act(async () => vi.advanceTimersByTime(4000));
  await click('.trigger-button');
  await act(async () => vi.advanceTimersByTime(4000));
  expect(document.querySelector('.live-notice')).not.toBeNull();
  await act(async () => vi.advanceTimersByTime(1000));
  expect(document.querySelector('.live-notice')).toBeNull();
  await click('.type-option.error');
  await click('.trigger-button');
  expect(document.querySelector('.live-notice.error')).not.toBeNull();
  await click('.close-button');
  expect(document.querySelector('.live-notice')).toBeNull();
  await act(async () => root.unmount());
  vi.useRealTimers();
  vi.unstubAllGlobals();
});
EOF
npx vitest run src/toast.smoke.test.tsx"

